// Generate synthetic arithmetic captcha PNGs + key.json (no deps). Same as evaluation generator.
import fs from 'node:fs'
import zlib from 'node:zlib'
const FONT = {
'0':['01110','10001','10011','10101','11001','10001','01110'],'1':['00100','01100','00100','00100','00100','00100','01110'],
'2':['01110','10001','00001','00010','00100','01000','11111'],'3':['11111','00010','00100','00010','00001','10001','01110'],
'4':['00010','00110','01010','10010','11111','00010','00010'],'5':['11111','10000','11110','00001','00001','10001','01110'],
'6':['00110','01000','10000','11110','10001','10001','01110'],'7':['11111','00001','00010','00100','01000','01000','01000'],
'8':['01110','10001','10001','01110','10001','10001','01110'],'9':['01110','10001','10001','01111','00001','00010','01100'],
'+':['00000','00100','00100','11111','00100','00100','00000'],'-':['00000','00000','00000','11111','00000','00000','00000'],
'x':['00000','10001','01010','00100','01010','10001','00000'],'=':['00000','00000','11111','00000','11111','00000','00000'],
'?':['01110','10001','00001','00010','00100','00000','00100'],' ':['00000','00000','00000','00000','00000','00000','00000'],
}
function crc32(b){let c=~0;for(let i=0;i<b.length;i++){c^=b[i];for(let k=0;k<8;k++)c=(c>>>1)^(0xEDB88320&-(c&1));}return ~c>>>0}
function chunk(t,d){const ty=Buffer.from(t,'ascii');const l=Buffer.alloc(4);l.writeUInt32BE(d.length);const cr=Buffer.alloc(4);cr.writeUInt32BE(crc32(Buffer.concat([ty,d])));return Buffer.concat([l,ty,d,cr])}
function encodePNG(w,h,rgba){const sig=Buffer.from([137,80,78,71,13,10,26,10]);const ih=Buffer.alloc(13);ih.writeUInt32BE(w,0);ih.writeUInt32BE(h,4);ih[8]=8;ih[9]=6;
  const raw=Buffer.alloc((w*4+1)*h);for(let y=0;y<h;y++){raw[y*(w*4+1)]=0;rgba.copy(raw,y*(w*4+1)+1,y*w*4,(y+1)*w*4)}
  return Buffer.concat([sig,chunk('IHDR',ih),chunk('IDAT',zlib.deflateSync(raw)),chunk('IEND',Buffer.alloc(0))])}
function render(text,scale,noise){const padX=8,padY=8,cw=6;const w=(text.length*cw+padX*2)*scale,h=(7+padY*2)*scale;
  const img=Buffer.alloc(w*h*4,255);for(let i=0;i<w*h*4;i+=4){img[i]=250;img[i+1]=250;img[i+2]=252;img[i+3]=255}
  const set=(x,y,r,g,b)=>{if(x<0||y<0||x>=w||y>=h)return;const o=(y*w+x)*4;img[o]=r;img[o+1]=g;img[o+2]=b;img[o+3]=255}
  let ox=padX;for(const ch of text){const gl=FONT[ch]||FONT['?'];for(let gy=0;gy<7;gy++)for(let gx=0;gx<5;gx++)if(gl[gy][gx]==='1')
    for(let sy=0;sy<scale;sy++)for(let sx=0;sx<scale;sx++)set((ox+gx)*scale+sx,(padY+gy)*scale+sy,20,60,180);ox+=cw}
  for(let n=0;n<noise;n++){const x=Math.floor(Math.random()*w),y=Math.floor(Math.random()*h);for(let t=0;t<6;t++)set(x+t,y+Math.floor(Math.sin(t)*2),150,150,160)}
  return encodePNG(w,h,img)}
const N=+(process.argv[2]||24),outdir=process.argv[3]||'.',key=[]
for(let i=0;i<N;i++){const op=['+','-','*'][Math.floor(Math.random()*3)];let a=Math.floor(Math.random()*9)+1,b=Math.floor(Math.random()*9)+1
  if(op==='-'&&b>a){[a,b]=[b,a]}
  const text=`${a}${op==='*'?'x':op}${b}?=`,ans=op==='+'?a+b:op==='-'?a-b:a*b
  fs.writeFileSync(`${outdir}/c${i}.png`,render(text,2,20));key.push({file:`c${i}.png`,text,answer:String(ans)})}
fs.writeFileSync(`${outdir}/key.json`,JSON.stringify(key,null,2));console.log('generated',N)

// Run the REAL skill script (default model) against generated captchas; compare to key.
import fs from 'node:fs'
import { execFileSync } from 'node:child_process'
const skill = 'D:/repository/skills/captcha-recognizer/scripts/solve-captcha.mjs'
const key = JSON.parse(fs.readFileSync('./key.json','utf8'))
let ok = 0
for (const it of key) {
  let out = ''
  try {
    out = execFileSync('node', [skill, './'+it.file, '--json'], { encoding: 'utf8' }).trim()
  } catch (e) { out = 'ERR:' + (e.message||'') }
  let ans = ''
  try { ans = JSON.parse(out).answer } catch { ans = out }
  const good = ans === it.answer
  if (good) ok++
  console.log(`${good?'OK':'XX'} ${it.text} truth=${it.answer} got=${ans} ${good?'':'<<< '+out}`)
}
console.log(`\n=== REAL skill default model: ${ok}/${key.length} = ${(100*ok/key.length).toFixed(1)}% ===`)
